def min_extra_tiles(hand):
    from collections import Counter

    # Count the occurrences of each tile
    count = Counter(hand)

    # Function to check if there is a koutsu
    def has_koutsu(count):
        return any(v >= 3 for v in count.values())

    # Function to check if there is a shuntsu
    def has_shuntsu(count):
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit in suits:
            tiles = suits[suit]
            for i in range(7):
                if count[tiles[i]] > 0 and count[tiles[i+1]] > 0 and count[tiles[i+2]] > 0:
                    return True
        return False

    # If there is already a mentsu, no need to draw any tiles
    if has_koutsu(count) or has_shuntsu(count):
        return 0

    # Otherwise, we need to draw at least one tile to form a mentsu
    return 1

