from collections import Counter

def min_extra_tiles(tiles):
    # Count the occurrences of each tile
    count = Counter(tiles)

    # Function to check if a koutsu can be formed
    def can_form_koutsu(count):
        return any(v >= 3 for v in count.values())

    # Function to check if a shuntsu can be formed
    def can_form_shuntsu(count):
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit in suits:
            tiles = [int(tile[0]) for tile in count if tile[1] == suit]
            tiles.sort()
            for i in range(len(tiles) - 2):
                if tiles[i+2] - tiles[i] == 2:
                    return True
        return False

    # Check if a mentsu can be formed without additional tiles
    if can_form_koutsu(count) or can_form_shuntsu(count):
        return 0

    # Calculate the minimum number of extra tiles needed
    extra_tiles = 0
    for tile, freq in count.items():
        if freq < 3:
            extra_tiles += 3 - freq

    # Ensure there is at least one shuntsu
    if not can_form_shuntsu(count):
        extra_tiles -= 1

    return extra_tiles

