from collections import Counter

def min_tiles_to_win(tiles):
    def can_form_mentsu(hand):
        count = Counter(hand)
        for i in range(1, 8):
            if count[f'{i}m'] >= 3 or count[f'{i}p'] >= 3 or count[f'{i}s'] >= 3:
                return True
            if count[f'{i}m'] >= 1 and count[f'{i+1}m'] >= 1 and count[f'{i+2}m'] >= 1:
                return True
            if count[f'{i}p'] >= 1 and count[f'{i+1}p'] >= 1 and count[f'{i+2}p'] >= 1:
                return True
            if count[f'{i}s'] >= 1 and count[f'{i+1}s'] >= 1 and count[f'{i+2}s'] >= 1:
                return True
        return False

    hand = sorted([tile[0] + tile[1] for tile in tiles])
    dp = [float('inf')] * (len(hand) + 1)
    dp[0] = 0

    for i in range(len(hand)):
        for j in range(i + 1, len(hand) + 1):
            new_hand = hand[:i] + hand[j:]
            if can_form_mentsu(new_hand):
                dp[j] = min(dp[j], dp[i])

    return dp[-1]

# Example usage:
if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    result = min_tiles_to_win(data)
    print(result)
