from collections import Counter

def min_tiles_to_draw(tiles):
    # Count the occurrences of each tile
    tile_count = Counter(tiles)

    # Initialize the count of additional tiles needed
    additional_tiles = 0

    # Check for koutsu (triplet)
    for tile in set(tiles):
        if tile_count[tile] < 3:
            additional_tiles += 3 - tile_count[tile]

    # Check for shuntsu (sequence)
    suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
    for suit in suits:
        suit_tiles = sorted([tile for tile in tiles if tile[1] == suit])
        if len(suit_tiles) >= 3:
            i = 0
            while i < len(suit_tiles) - 2:
                if int(suit_tiles[i][0]) + 1 == int(suit_tiles[i+1][0]) and int(suit_tiles[i+1][0]) + 1 == int(suit_tiles[i+2][0]):
                    i += 3
                else:
                    additional_tiles += 1
                    i += 1

    return additional_tiles

