from collections import Counter

def min_extra_tiles(tiles):
    # Count occurrences of each tile
    count = Counter(tiles)

    # Check for koutsu
    for tile in set(tiles):
        if count[tile] >= 3:
            return 0

    # Check for shuntsu
    suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
    for suit in suits:
        numbers = suits[suit]
        for i in range(len(numbers) - 2):
            if all(f'{numbers[i]}{suit}' in count and f'{numbers[j]}{suit}' in count and f'{numbers[k]}{suit}' in count for j in range(i+1, i+3) for k in range(j+1, j+3)):
                return 0

    # If no mentsu found, draw one tile
    return 1

# Read input
tiles = input().split()

# Output result
print(min_extra_tiles(tiles))
