def min_extra_tiles(tiles):
    # Count the occurrences of each tile
    tile_count = Counter(tiles)

    # Function to check if there is a koutsu
    def has_koutsu():
        return any(count >= 3 for count in tile_count.values())

    # Function to check if there is a shuntsu
    def has_shuntsu():
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit, numbers in suits.items():
            for i in range(len(numbers) - 2):
                if all(tile_count[f'{numbers[i]}{suit}'] > 0 for _ in range(3)):
                    return True
        return False

    # If there is already a mentsu, no need to draw any extra tiles
    if has_koutsu() or has_shuntsu():
        return 0

    # Calculate the minimum number of extra tiles needed
    extra_tiles = 0
    for tile, count in tile_count.items():
        if count < 3:
            extra_tiles += 3 - count

    # Ensure we have enough tiles to form a shuntsu if necessary
    if not has_shuntsu():
        extra_tiles -= 3

    return max(extra_tiles, 0)

