from collections import Counter

def min_extra_tiles(tiles):
    # Count the occurrences of each tile
    count = Counter(tiles)

    # Function to check if a koutsu can be formed
    def can_form_koutsu():
        return any(count[tile] >= 3 for tile in count)

    # Function to check if a shuntsu can be formed
    def can_form_shuntsu():
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit in suits:
            tiles_in_suit = [tile for tile in count if tile[1] == suit]
            tiles_in_suit.sort()
            for i in range(len(tiles_in_suit) - 2):
                if int(tiles_in_suit[i][0]) + 1 == int(tiles_in_suit[i+1][0]) and \
                   int(tiles_in_suit[i+1][0]) + 1 == int(tiles_in_suit[i+2][0]):
                    return True
        return False

    # Check if any mentsu can be formed
    if can_form_koutsu() or can_form_shuntsu():
        return 0

    # If no mentsu can be formed, calculate the minimum number of extra tiles needed
    extra_tiles_needed = 0
    for tile in count:
        if count[tile] < 3:
            extra_tiles_needed += 3 - count[tile]

    # Ensure we have enough tiles to form at least one mentsu
    if extra_tiles_needed % 3 != 0:
        extra_tiles_needed += 3 - (extra_tiles_needed % 3)

    return extra_tiles_needed // 3

