def min_extra_tiles(tiles):
    # Convert the input strings to tuples (number, suit)
    tiles = [(int(tile[0]), tile[1]) for tile in tiles.split()]

    # Count occurrences of each tile
    count = {}
    for num, suit in tiles:
        if (num, suit) in count:
            count[(num, suit)] += 1
        else:
            count[(num, suit)] = 1

    # Check for existing mentsu
    def has_koutsu(count):
        for num, suit in count:
            if count[(num, suit)] >= 3:
                return True
        return False

    def has_shuntsu(count):
        suits = set(suit for _, suit in count)
        for suit in suits:
            nums = sorted(num for num, s in count if s == suit)
            for i in range(len(nums) - 2):
                if nums[i+1] == nums[i] + 1 and nums[i+2] == nums[i] + 2:
                    return True
        return False

    if has_koutsu(count) or has_shuntsu(count):
        return 0

    # If no mentsu exists, calculate the minimum number of extra tiles needed
    extra_tiles = 0
    if not has_koutsu(count):
        extra_tiles += 3 - max(count.values())
    if not has_shuntsu(count):
        extra_tiles += 3 - len(count)

    return extra_tiles

