from collections import Counter

def min_extra_tiles(tiles):
    # Count the occurrences of each tile
    count = Counter(tiles)

    # Function to check if we can form a koutsu with the given count
    def can_form_koutsu(count):
        return any(v >= 3 for v in count.values())

    # Function to check if we can form a shuntsu with the given count
    def can_form_shuntsu(count):
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit in suits:
            tiles = ''.join([str(i) + suit for i in range(1, 10)])
            for i in range(len(tiles) - 2):
                if all(count[tiles[i+j]] > 0 for j in range(3)):
                    for j in range(3):
                        count[tiles[i+j]] -= 1
                    if can_form_koutsu(count):
                        for j in range(3):
                            count[tiles[i+j]] += 1
                        return True
                    for j in range(3):
                        count[tiles[i+j]] += 1
        return False

    # Check if we can form a mentsu without any additional tiles
    if can_form_koutsu(count) or can_form_shuntsu(count):
        return 0

    # Calculate the minimum number of extra tiles needed
    extra_tiles = float('inf')
    for tile in set(tiles):
        count[tile] += 1
        if can_form_koutsu(count) or can_form_shuntsu(count):
            extra_tiles = min(extra_tiles, 1)
        count[tile] -= 1

    return extra_tiles

